// src/modules/dashboard/Dashboard.js
import React, { useMemo, useState } from "react";
import Sidebar from "../../components/Sidebar";
import Header from "../../components/Header";
import TopCandidates from "../../components/TopCandidates";
import TopJobsProjects from "../../components/TopJobsProjects";
import "./Dashboard.css";
import "../../index.css"; // keep global styles
import { FaUsers, FaDollarSign, FaChartLine, FaUserCheck } from "react-icons/fa";

const readJson = (key, fallback = []) => {
  try {
    return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback));
  } catch (e) {
    return fallback;
  }
};

// ======================== COMPANY DASHBOARD ========================
function CompanyDashboard({ jobs, projects, setJobs, setProjects, metrics }) {
  const [showJobForm, setShowJobForm] = useState(false);
  const [showProjectForm, setShowProjectForm] = useState(false);

  const [jobForm, setJobForm] = useState({
    job_title: "",
    job_description: "",
    job_type: "",
    required_experience: "",
    required_skills: "",
    work_mode: "",
    salary: "",
    preferred_domain: "",
    created_at: "",
  });

  const [projectForm, setProjectForm] = useState({
    project_title: "",
    project_description: "",
    project_type: "",
    payment_type: "",
    work_mode: "",
    required_experience: "",
    required_skills: "",
    team_size: "",
    duration: "",
    domain: "",
    salary: "",
    created_at: "",
  });

  const handleJobSubmit = (e) => {
    e.preventDefault();
    const updated = [...jobs, { ...jobForm, id: Date.now() }];
    setJobs(updated);
    localStorage.setItem("jobs", JSON.stringify(updated));
    setShowJobForm(false);
    alert("Job posted!");
  };

  const handleProjectSubmit = (e) => {
    e.preventDefault();
    const updated = [...projects, { ...projectForm, id: Date.now() }];
    setProjects(updated);
    localStorage.setItem("projects", JSON.stringify(updated));
    setShowProjectForm(false);
    alert("Project posted!");
  };

  return (
    <div>
      {/* Action buttons */}
      <div className="dashboard-section-actions" style={{ display: "flex", gap: 12, marginBottom: 18 }}>
        <button className="btn-primary" onClick={() => setShowJobForm(!showJobForm)}>
          Post a Job
        </button>
        <button className="btn-primary" onClick={() => setShowProjectForm(!showProjectForm)}>
          Post a Project
        </button>
      </div>

      {/* Job form */}
      {showJobForm && (
        <div className="dashboard-form-card">
          <h3>Post Job</h3>
          <form onSubmit={handleJobSubmit}>
            <input required placeholder="Job title" value={jobForm.job_title} onChange={(e) => setJobForm({ ...jobForm, job_title: e.target.value })} />
            <textarea required placeholder="Job description" value={jobForm.job_description} onChange={(e) => setJobForm({ ...jobForm, job_description: e.target.value })} />
            <input placeholder="Job type" value={jobForm.job_type} onChange={(e) => setJobForm({ ...jobForm, job_type: e.target.value })} />
            <input placeholder="Required experience" value={jobForm.required_experience} onChange={(e) => setJobForm({ ...jobForm, required_experience: e.target.value })} />
            <input placeholder="Required skills" value={jobForm.required_skills} onChange={(e) => setJobForm({ ...jobForm, required_skills: e.target.value })} />
            <input placeholder="Work mode" value={jobForm.work_mode} onChange={(e) => setJobForm({ ...jobForm, work_mode: e.target.value })} />
            <input placeholder="Salary" value={jobForm.salary} onChange={(e) => setJobForm({ ...jobForm, salary: e.target.value })} />
            <input placeholder="Preferred domain" value={jobForm.preferred_domain} onChange={(e) => setJobForm({ ...jobForm, preferred_domain: e.target.value })} />
            <input placeholder="Created at (YYYY-MM-DD)" value={jobForm.created_at} onChange={(e) => setJobForm({ ...jobForm, created_at: e.target.value })} />
            <button type="submit" className="btn-primary" style={{ marginTop: 8 }}>
              Create Job
            </button>
          </form>
        </div>
      )}

      {/* Project form */}
      {showProjectForm && (
        <div className="dashboard-form-card">
          <h3>Post Project</h3>
          <form onSubmit={handleProjectSubmit}>
            <input required placeholder="Project title" value={projectForm.project_title} onChange={(e) => setProjectForm({ ...projectForm, project_title: e.target.value })} />
            <textarea required placeholder="Project description" value={projectForm.project_description} onChange={(e) => setProjectForm({ ...projectForm, project_description: e.target.value })} />
            <input placeholder="Project type" value={projectForm.project_type} onChange={(e) => setProjectForm({ ...projectForm, project_type: e.target.value })} />
            <input placeholder="Payment type" value={projectForm.payment_type} onChange={(e) => setProjectForm({ ...projectForm, payment_type: e.target.value })} />
            <input placeholder="Work mode" value={projectForm.work_mode} onChange={(e) => setProjectForm({ ...projectForm, work_mode: e.target.value })} />
            <input placeholder="Required experience" value={projectForm.required_experience} onChange={(e) => setProjectForm({ ...projectForm, required_experience: e.target.value })} />
            <input placeholder="Required skills" value={projectForm.required_skills} onChange={(e) => setProjectForm({ ...projectForm, required_skills: e.target.value })} />
            <input placeholder="Team size" value={projectForm.team_size} onChange={(e) => setProjectForm({ ...projectForm, team_size: e.target.value })} />
            <input placeholder="Duration" value={projectForm.duration} onChange={(e) => setProjectForm({ ...projectForm, duration: e.target.value })} />
            <input placeholder="Domain" value={projectForm.domain} onChange={(e) => setProjectForm({ ...projectForm, domain: e.target.value })} />
            <input placeholder="Budget/Salary" value={projectForm.salary} onChange={(e) => setProjectForm({ ...projectForm, salary: e.target.value })} />
            <input placeholder="Created at (YYYY-MM-DD)" value={projectForm.created_at} onChange={(e) => setProjectForm({ ...projectForm, created_at: e.target.value })} />
            <button type="submit" className="btn-primary" style={{ marginTop: 8 }}>
              Create Project
            </button>
          </form>
        </div>
      )}

      {/* Metrics */}
      <div style={{ marginTop: 18 }} className="cards-container">
        <div className="card">
          <div className="card-icon"><FaUsers /></div>
          <div className="card-info">
            <p className="card-title">Active Candidates</p>
            <p className="card-value">{metrics.activeCandidates.toLocaleString()}</p>
          </div>
        </div>

        <div className="card">
          <div className="card-icon"><FaUserCheck /></div>
          <div className="card-info">
            <p className="card-title">Avg Match Score</p>
            <p className="card-value">{metrics.avgMatchScore}%</p>
          </div>
        </div>

        <div className="card">
          <div className="card-icon"><FaDollarSign /></div>
          <div className="card-info">
            <p className="card-title">Revenue This Month</p>
            <p className="card-value">${Number(metrics.revenueThisMonth).toLocaleString()}</p>
          </div>
        </div>

        <div className="card">
          <div className="card-icon"><FaChartLine /></div>
          <div className="card-info">
            <p className="card-title">Active Deals</p>
            <p className="card-value">{metrics.activeDeals}</p>
          </div>
        </div>
      </div>

      {/* Only company sees candidates */}
      <div style={{ marginTop: 28 }}>
        <TopCandidates />
      </div>
    </div>
  );
}

// ======================== FREELANCER / JOBSEEKER ========================
function FreelancerDashboard({ jobs, projects }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  const randomTopJobs = useMemo(() => {
    const shuffled = [...jobs].sort(() => 0.5 - Math.random());
    return shuffled.slice(0, 5);
  }, [jobs]);

  const handleSearch = (e) => {
    e.preventDefault();
    const q = query.trim().toLowerCase();
    const matchedJobs = jobs.filter(j => (j.preferred_domain || j.domain || "").toLowerCase().includes(q));
    const matchedProjects = projects.filter(p => (p.domain || "").toLowerCase().includes(q));
    setResults([...matchedJobs.slice(0, 5), ...matchedProjects.slice(0, 5)]);
  };

  return (
    <div>
      <form onSubmit={handleSearch} style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <input placeholder="Search domain or skill..." value={query} onChange={(e) => setQuery(e.target.value)} />
        <button className="btn-primary" type="submit">Search</button>
      </form>

      <div style={{ marginTop: 14 }}>
        <h3>Top Jobs & Projects</h3>
        <TopJobsProjects />
      </div>

      {results.length > 0 && (
        <div style={{ marginTop: 18 }}>
          <h3>Search Results</h3>
          <div className="list-grid">
            {results.map((r, i) => (
              <div key={i} className="dashboard-item-card">
                <strong>{r.job_title || r.project_title}</strong>
                <p className="muted">{(r.job_description || r.project_description || "").slice(0, 120)}...</p>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const JobSeekerDashboard = FreelancerDashboard;

// ======================== MAIN DASHBOARD ========================
function Dashboard() {
  const jobs = readJson("jobs", []);
  const projects = readJson("projects", []);
  const freelancerProfiles = readJson("freelancerProfiles", []);
  const jobSeekerProfiles = readJson("jobSeekerProfiles", []);
  const companyProfiles = readJson("companyProfiles", []);

  const metrics = {
    activeCandidates: freelancerProfiles.length + jobSeekerProfiles.length || 2847,
    avgMatchScore: 87,
    revenueThisMonth: localStorage.getItem("revenueThisMonth") || 124500,
    activeDeals: localStorage.getItem("activeDeals") || 47,
  };

  let role = "guest";
  try {
    const cu = JSON.parse(localStorage.getItem("currentUser") || "null");
    if (cu?.role) role = cu.role;
    else if (cu?.email) {
      const email = cu.email;
      if (companyProfiles.find(c => c.user_id === email || c.company_name === email)) role = "company";
      else if (freelancerProfiles.find(f => f.email === email)) role = "freelancer";
      else if (jobSeekerProfiles.find(j => j.email === email)) role = "jobseeker";
    }
  } catch {
    role = "guest";
  }

  const [jobsState, setJobsState] = useState(jobs);
  const [projectsState, setProjectsState] = useState(projects);

  return (
    <div className="dashboard-container">
      <Sidebar />
      <div className="dashboard-main">
        <Header />
        <div className="dashboard-content">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18 }}>
            <div>
              <h1 className="dashboard-title">Dashboard</h1>
              <p style={{ margin: 0, color: "#556070" }}>Welcome back</p>
            </div>
          </div>

          {/* Metric cards */}
          <div className="cards-container">
            <div className="card">
              <div className="card-icon"><FaUsers /></div>
              <div className="card-info">
                <p className="card-title">Active Candidates</p>
                <p className="card-value">{metrics.activeCandidates.toLocaleString()} <span className="up-arrow">▲ 12.5%</span></p>
              </div>
            </div>

            <div className="card">
              <div className="card-icon"><FaUserCheck /></div>
              <div className="card-info">
                <p className="card-title">Avg Match Score</p>
                <p className="card-value">{metrics.avgMatchScore}% <span className="up-arrow">▲ 5.2%</span></p>
              </div>
            </div>

            <div className="card">
              <div className="card-icon"><FaDollarSign /></div>
              <div className="card-info">
                <p className="card-title">Revenue This Month</p>
                <p className="card-value">${Number(metrics.revenueThisMonth).toLocaleString()} <span className="up-arrow">▲ 8.1%</span></p>
              </div>
            </div>

            <div className="card">
              <div className="card-icon"><FaChartLine /></div>
              <div className="card-info">
                <p className="card-title">Active Deals</p>
                <p className="card-value">{metrics.activeDeals} <span className="down-arrow">▼ 2.4%</span></p>
              </div>
            </div>
          </div>

          {/* Role-specific section */}
          <div style={{ marginTop: 22 }}>
            {role === "company" && (
              <CompanyDashboard jobs={jobsState} projects={projectsState} setJobs={setJobsState} setProjects={setProjectsState} metrics={metrics} />
            )}
            {role === "freelancer" && <FreelancerDashboard jobs={jobsState} projects={projectsState} />}
            {role === "jobseeker" && <JobSeekerDashboard jobs={jobsState} projects={projectsState} />}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
